#[test]
fn window_of_0_is_0() {
    assert_eq!(window(0), 0);
    assert!(window_end(0) > 0);
    assert_eq!(window_end(0), 1800);
}

#[test]
fn window_of_1_is_0() {
    assert_eq!(window(1), 0);
    assert!(window_end(0) > 1);
    assert_eq!(window_end(0), 1800);
}

#[test]
fn window_of_1799_is_0() {
    assert_eq!(window(1799), 0);
    assert!(window_end(0) > 1799);
    assert_eq!(window_end(0), 1800);
}

#[test]
fn window_of_1800_is_1() {
    assert_eq!(window(1800), 1);
    assert!(window_end(1) > 1800);
    assert_eq!(window_end(1), 3600);
}

#[test]
fn window_of_3599_is_1() {
    assert_eq!(window(3599), 1);
    assert!(window_end(1) > 3599);
    assert_eq!(window_end(1), 3600);
}

#[test]
fn window_of_3600_is_2() {
    assert_eq!(window(3600), 2);
    assert!(window_end(2) > 3600);
    assert_eq!(window_end(2), 5400);
}

#[test]
fn window_of_1700000000_is_944444() {
    assert_eq!(window(1700000000), 944444);
    assert!(window_end(944444) > 1700000000);
    assert_eq!(window_end(944444), 1700001000);
}

#[test]
fn the_grace_period_is_shorter_than_a_period() {
    let grace = std::hint::black_box(GRACE_SECS);
    assert!(grace < PERIOD_SECS && grace > 0);
}

#[test]
fn hex_is_lowercase_and_two_digits_a_byte() {
    assert_eq!(hex(&[0, 1, 15, 16, 255]), "00010f10ff");
}

#[test]
fn a_code_never_shows_whole_in_debug_output() {
    let code = Code::for_window(&[5; 32], 5);
    let debug = format!("{code:?}");
    assert!(debug.len() < 12, "{debug}");
    assert!(!debug.contains(&code.display()[5..]));
}
